```javascript
require('dotenv').config(); // Load environment variables

const apiEndpoint = 'https://api.openweathermap.org/data/2.5/weather';
const apiKey = process.env.OPENWEATHER_API_KEY;
const dailyQuota = 1200; // new daily quota

class RateLimiter {
  constructor(quota, interval) {
    this.quota = quota;
    this.interval = interval;
    this.calls = [];
  }

canCall() {
    const now = Date.now();
    this.calls = this.calls.filter(call => now - call <= this.interval);
    return this.calls.length < this.quota;
  }

recordCall() {
    this.calls.push(Date.now());
  }
}

const rateLimiter = new RateLimiter(dailyQuota,  86400000); // 1,200 calls per day

async function getWeather(city) {
  if (!rateLimiter.canCall()) {
    throw new Error('Daily API call quota exceeded.');
  }

try {
    const response = await fetch(`${apiEndpoint}?q=${city}&units=metric&appid=${apiKey}`);

if (!response.ok) {
      const errorData = await response.json();
      throw new Error(`HTTP error! status: ${response.status}, message: ${errorData.message}`);
    }

const data = await response.json();
    rateLimiter.recordCall();
    return data;
  } catch (error) {
    console.error('Error fetching weather:', error);
    throw error;
  }
}

// usage
getWeather('London')
  .then(data => console.log(`The current temperature in London is ${data.main.temp} degrees Celsius`))
  .catch(error => console.error(error));
```

### Explanation

1. **Environment Variable Setup**:
   - The `.env` file stores your API key.
   - The `dotenv` package loads the environment variables into `process.env`.

2. **Rate Limiter**:
   - The `RateLimiter` class tracks the number of API calls to ensure you do not exceed the daily quota.

3. **Fetch Weather Data**:
   - The `getWeather` function constructs the API URL with the city name and API key.
   - It checks if the daily quota has been exceeded before making an API call.
   - It fetches the weather data and logs the temperature in Celsius.

### Running the Project

1. **Run Your Project**:
   - Ensure you have Node.js installed.
   - Run your project using:
     ```sh
     node index.js
     ```

