```javascript
// autocomplete.js
import LRU from 'lru-cache';

const cache = new LRU({
  max: 100,
  maxAge: 1000 * 60 * 5 // Cache entries expire after 5 minutes
});

function debounce(func, wait) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => func.apply(this, args), wait);
  };
}

function autocomplete(input, options) {
  const { apiKey, apiUrl, debounceTime } = options;
  const autocompleteList = document.getElementById(options.listId);
  const loadingIndicator = document.getElementById(options.loadingId);

function showLoading() {
    loadingIndicator.style.display = 'block';
  }

function hideLoading() {
    loadingIndicator.style.display = 'none';
  }

function renderResults(results) {
    autocompleteList.innerHTML = '';
    if (results.length === 0) {
      const listItem = document.createElement('li');
      listItem.textContent = 'No results found';
      autocompleteList.appendChild(listItem);
      return;
    }

results.forEach((result) => {
      if (result && result.name && result.country) {
        const listItem = document.createElement('li');
        listItem.textContent = `${result.name}, ${result.country}`;
        autocompleteList.appendChild(listItem);
      } else {
        console.error('Invalid result data:', result);
      }
    });
  }

async function fetchCityData(query) {
    showLoading();

if (cache.has(query)) {
      hideLoading();
      return cache.get(query);
    }

try {
      const response = await fetch(`${apiUrl}?q=${query}&limit=5&appid=${apiKey}`);

if (!response.ok) {
        const data = await response.json();
        throw new Error(`HTTP error! status: ${response.status}, message: ${data.message}`);
      }

const data = await response.json();
      cache.set(query, data);
      hideLoading();
      return data;
    } catch (error) {
      hideLoading();
      console.error('Error fetching city data:', error);
      return [];
    }
  }

const handleInputChange = debounce(async (event) => {
    const query = event.target.value.trim();
    if (query.length < 3) {
      renderResults([]);
      return;
    }

const cityData = await fetchCityData(query);
    renderResults(cityData);
  }, debounceTime);

input.addEventListener('input', handleInputChange);
}

// options
const options = {
  apiKey: 'YOUR_API_KEY',
  apiUrl: 'https://api.openweathermap.org/geo/1.0/direct',
  debounceTime: 300,
  listId: 'autocomplete-list',
  loadingId: 'loading-indicator'
};

// usage
const input = document.getElementById('input');
autocomplete(input, options);
```

