const autocompleteDropdown = document.getElementById('autocomplete-dropdown');

const fetchAutocompleteSuggestions = async (inputValue) => {
  try {
    const response = await fetch(`https://api.openweathermap.org/geo/1.0/direct?q=${inputValue}&limit=5&appid=YOUR_API_KEY`);

if (!response.ok) {
      const errorData = await response.json();
      const errorMessage = errorData.message || `HTTP error! status: ${response.status}`;
      throw new Error(errorMessage);
    }

const suggestions = await response.json();

// Render the suggestions in the dropdown
    autocompleteDropdown.innerHTML = '';
    suggestions.forEach((suggestion) => {
      if (suggestion && suggestion.name) {
        const suggestionElement = document.createElement('li');
        suggestionElement.textContent = suggestion.name;
        autocompleteDropdown.appendChild(suggestionElement);
      }
    });
  } catch (error) {
    if (error.response && error.response.status === 401) {
      console.error('Invalid API key');
    } else {
      console.error('Error fetching autocomplete suggestions:', error);
    }
  }
};

const handleAutocompleteInput = debounce((inputValue) => {
  fetchAutocompleteSuggestions(inputValue);
}, 300);

autocompleteInput.addEventListener('input', (event) => {
  handleAutocompleteInput(event.target.value);
});
