async function getWeather(city) {
  const url = `https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=${apiKey}`;
  const response = await fetch(url);

if (!response.ok) {
    const errorData = await response.json();
    if (response.status === 404) {
      throw new Error('City not found');
    } else if (response.status === 400) {
      throw new Error('Bad request');
    } else {
      throw new Error(`HTTP error! status: ${response.status}, message: ${errorData.message}`);
    }
  }

const data = await response.json();
  return data;
}

// Function to display weather data
function displayWeather(data) {
  const temperature = data.main.temp;
  const humidity = data.main.humidity;
  const conditions = data.weather[0].description;
  const conditionIconUrl = `http://openweathermap.org/img/wn/${data.weather[0].icon}@2x.png`;

document.getElementById('temperature').textContent = `Temperature: ${temperature} &deg;C`;
  document.getElementById('humidity').textContent = `Humidity: ${humidity}%`;
  document.getElementById('conditions').textContent = `Conditions: ${conditions}`;
  document.getElementById('condition-icon').src = conditionIconUrl;
  document.getElementById('condition-icon').alt = conditions;

document.getElementById('weather-data').style.display = 'block';
