class RateLimiter {
  constructor(quota, interval) {
    this.quota = quota;
    this.interval = interval;
    this.calls = [];
  }

canCall() {
    const now = Date.now();
    this.calls = this.calls.filter(call => now - call <= this.interval);
    return this.calls.length < this.quota;
  }

recordCall() {
    this.calls.push(Date.now());
  }
}

